import { Room, RoomEvent, TokenSource, Track } from 'livekit-client';
import { useEffect, useRef, useState } from 'react';
import './Walkie.css'


function Walkie(props) {
    const roomRef = useRef(null)
    const audioContainerRef = useRef(null)

    const [walkieActive, setWalkieActive] = useState(false)
    const [needsAudioStart, setNeedsAudioStart] = useState(false)
    const [connected, setConnected] = useState(false)

    useEffect(() => {
        const room = new Room()
        roomRef.current = room

        const handleTrackSubscribed = (track) => {
            if (track.kind !== Track.Kind.Audio) return
            const audioEl = track.attach()
            audioEl.autoplay = true
            audioContainerRef.current?.appendChild(audioEl)
        }

        const handleTrackUnsubscribed = (track) => {
            track.detach().forEach((el) => el.remove())
        }

        const handleAudioPlaybackChanged = () => {
            if (!room.canPlaybackAudio) {
                setNeedsAudioStart(true)
            } else {
                setNeedsAudioStart(false)
            }
        }

        room.on(RoomEvent.TrackSubscribed, handleTrackSubscribed)
        room.on(RoomEvent.TrackUnsubscribed, handleTrackUnsubscribed)
        room.on(RoomEvent.AudioPlaybackStatusChanged, handleAudioPlaybackChanged)
        room.on(RoomEvent.Connected, () => setConnected(true))
        room.on(RoomEvent.Disconnected, () => setConnected(false))

        async function connectToRoom() {
            const tokenSource = TokenSource.sandboxTokenServer("lanelinkbeta-1r2rkc")

            const { serverUrl, participantToken } = await tokenSource.fetch({
                roomName: "room name to join",
            })

            await room.connect(serverUrl, participantToken, { autoSubscribe: true })
        }
        connectToRoom().catch((err) => console.error("Error connecting to room:", err))

        return () => {
            room.off(RoomEvent.TrackSubscribed, handleTrackSubscribed)
            room.off(RoomEvent.TrackUnsubscribed, handleTrackUnsubscribed)
            room.off(RoomEvent.AudioPlaybackStatusChanged, handleAudioPlaybackChanged)
            room.disconnect()
        }
    }, [])

    async function handleWalkieToggle(e) {
        if (!roomRef.current) return

        if (e.type === 'pointerdown') {
            try {
                await roomRef.current.localParticipant.setMicrophoneEnabled(true)
                setWalkieActive(true)
            } catch (error) {
                console.error("Error enabling microphone:", error)
            }
        } else if (e.type === 'pointerup' || e.type === 'pointercancel') {
            try {
                setWalkieActive(false)
                await roomRef.current.localParticipant.setMicrophoneEnabled(false)
            } catch (error) {
                console.error("Error disabling microphone:", error)
            }
        }
    }

    function handleEnableAudio() {
        roomRef.current?.startAudio().then(() => setNeedsAudioStart(false))
    }

    return (
        <div className="walkie">
            <h1>Walkie Talkie</h1>

            {needsAudioStart && (
                <button className="enable-audio" onClick={handleEnableAudio}>
                    Tap to enable audio
                </button>
            )}

            <button
                className={walkieActive ? 'active' : 'inactive'}
                disabled={!connected}
                onPointerDown={handleWalkieToggle}
                onPointerUp={handleWalkieToggle}
                onPointerCancel={handleWalkieToggle}
            >
                <i className="fa-solid fa-walkie-talkie"></i>Push To Talk
            </button>

            {/* hidden container where remote audio elements are appended */}
            <div ref={audioContainerRef} style={{ display: 'none' }} />
        </div>
    )
}

export default Walkie